:root {
  --card-bg: #ffffff;
  --header-bg: #2d6a4f;
  --header-text: #ffffff;
  --batch-number: #95d5b2;
  --status-bg: #b7e4c7;
  --status-text: #1b4332;
  --tea-text: #d8f3dc;
  --stage-done: #52b788;
  --stage-active: #f4a261;
  --stage-inactive: #ced4da;
  --line-done: #52b788;
  --line-active: #f4a261;
  --line-inactive: #ced4da;
  --metric-value: #1b4332;
  --metric-unit: #52b788;
  --metric-label: #6c757d;
  --metric-border: #e9ecef;
  --flavor-bg: #f0fdf4;
  --flavor-border: #b7e4c7;
  --flavor-text: #2d6a4f;
  --footer-bg: #f8f9fa;
  --footer-border: #e9ecef;
  --date-text: #495057;
  --btn-bg: #2d6a4f;
  --btn-text: #ffffff;
  --btn-hover: #1b4332;
}

article.batch-card {
  background: var(--card-bg);
  border-radius: 14px;
  overflow: hidden;
  width: 440px;
  border: 1px solid var(--metric-border);
}

.batch-header {
  background: var(--header-bg);
  padding: 14px 18px 12px;
}

.batch-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 4px;
}

.batch-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--batch-number);
  opacity: 0.8;
}

.batch-number {
  font-size: 18px;
  font-weight: 700;
  color: var(--header-text);
}

.batch-status {
  background: var(--status-bg);
  color: var(--status-text);
  font-size: 11px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 20px;
  margin-left: auto;
}

.batch-tea {
  font-size: 13px;
  color: var(--tea-text);
  margin: 0;
}

.batch-body {
  padding: 16px 18px;
}

.ferment-stages {
  display: flex;
  align-items: center;
  margin-bottom: 16px;
}

.stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.stage-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--stage-inactive);
}

.stage-done .stage-dot {
  background: var(--stage-done);
}

.stage-active .stage-dot {
  background: var(--stage-active);
  outline: 3px solid #fde8d8;
}

.stage-name {
  font-size: 11px;
  font-weight: 600;
  color: var(--metric-label);
}

.stage-done .stage-name {
  color: var(--stage-done);
}

.stage-active .stage-name {
  color: var(--stage-active);
}

.stage-line {
  flex: 1;
  height: 3px;
  background: var(--line-inactive);
  border-radius: 2px;
  margin-bottom: 16px;
}

.stage-line-done {
  background: var(--line-done);
}

.stage-line-active {
  background: var(--line-active);
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.metric {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 8px;
  border: 1px solid var(--metric-border);
  border-radius: 10px;
  background: var(--flavor-bg);
}

.metric-value {
  font-size: 17px;
  font-weight: 700;
  color: var(--metric-value);
  line-height: 1.1;
}

.metric-unit {
  font-size: 11px;
  font-weight: 600;
  color: var(--metric-unit);
  min-height: 14px;
}

.metric-label {
  font-size: 11px;
  color: var(--metric-label);
  margin-top: 2px;
}

.flavor-row {
  display: flex;
  gap: 8px;
  padding: 0 18px 14px;
  flex-wrap: wrap;
}

.flavor-tag {
  background: var(--flavor-bg);
  border: 1px solid var(--flavor-border);
  color: var(--flavor-text);
  font-size: 12px;
  font-weight: 500;
  padding: 5px 12px;
  border-radius: 20px;
}

.batch-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  background: var(--footer-bg);
  border-top: 1px solid var(--footer-border);
}

.footer-dates {
  display: flex;
  gap: 16px;
}

.date-item {
  font-size: 12px;
  color: var(--date-text);
}

.date-item strong {
  color: var(--metric-value);
}

.log-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
